               v(40,1) = paz*v(37,1) + wpz*v(37,0) &
                  + 2.0_dp*oo2ze*v(13,0)

            do k = 1, 40
               g(k) = g(k) + v(k,1)
            end do
         end do

               out(1) = out(1) + g(18)
               out(2) = out(2) + g(19)
               out(3) = out(3) + g(20)
               out(4) = out(4) + g(22)
               out(5) = out(5) + g(23)
               out(6) = out(6) + g(24)
               out(7) = out(7) + g(26)
