   end subroutine df_2c13


   !> (a|c) class (20|0) -- 15 VRR statements after the sieve.
   pure subroutine df_2c20(nprim_a, ea, ca, ra, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_c
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a), ra(3)
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(6)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(10,0:1), g(10)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 6
         out(k) = 0.0_dp
      end do

      do ip = 1, nprim_a
         al = ea(ip)
         zeta = al
         kab = ca(ip)
         px = ra(1); py = ra(2); pz = ra(3)
         pax = 0.0_dp; pay = 0.0_dp; paz = 0.0_dp

         do k = 1, 10
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(2, tval, f)

               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               ! --- level m = 1 ---
               v(1,1) = pref*f(1)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 0 ---
               v(1,0) = pref*f(0)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(6,0) = pax*v(3,0) + wpx*v(3,1)
               v(7,0) = pax*v(4,0) + wpx*v(4,1)
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(9,0) = pay*v(4,0) + wpy*v(4,1)
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))

            do k = 1, 10
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + g(5)
               out(2) = out(2) + g(6)
               out(3) = out(3) + g(7)
               out(4) = out(4) + g(8)
               out(5) = out(5) + g(9)
               out(6) = out(6) + g(10)
      end do

   end subroutine df_2c20


   !> (a|c) class (20|1) -- 49 VRR statements after the sieve.
   pure subroutine df_2c21(nprim_a, ea, ca, ra, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_c
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a), ra(3)
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(18)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(40,0:1), g(40)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 18
         out(k) = 0.0_dp
      end do

      do ip = 1, nprim_a
         al = ea(ip)
         zeta = al
         kab = ca(ip)
         px = ra(1); py = ra(2); pz = ra(3)
         pax = 0.0_dp; pay = 0.0_dp; paz = 0.0_dp

         do k = 1, 40
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(3, tval, f)

               ! --- level m = 3 ---
               v(1,0) = pref*f(3)
               ! --- level m = 2 ---
               v(1,1) = pref*f(2)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 1 ---
               v(1,0) = pref*f(1)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(11,0) = qcx*v(1,0) + wqx*v(1,1)
               v(21,0) = qcy*v(1,0) + wqy*v(1,1)
               v(31,0) = qcz*v(1,0) + wqz*v(1,1)
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(12,0) = qcx*v(2,0) + wqx*v(2,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(14,0) = qcx*v(4,0) + wqx*v(4,1)
               v(22,0) = qcy*v(2,0) + wqy*v(2,1)
               v(24,0) = qcy*v(4,0) + wqy*v(4,1)
               v(32,0) = qcz*v(2,0) + wqz*v(2,1)
               v(34,0) = qcz*v(4,0) + wqz*v(4,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               ! --- level m = 0 ---
               v(1,1) = pref*f(0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(11,1) = qcx*v(1,1) + wqx*v(1,0)
               v(21,1) = qcy*v(1,1) + wqy*v(1,0)
               v(31,1) = qcz*v(1,1) + wqz*v(1,0)
               v(8,1) = pay*v(3,1) + wpy*v(3,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(12,1) = pax*v(11,1) + wpx*v(11,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(14,1) = paz*v(11,1) + wpz*v(11,0)
               v(22,1) = pax*v(21,1) + wpx*v(21,0)
               v(24,1) = paz*v(21,1) + wpz*v(21,0)
               v(32,1) = pax*v(31,1) + wpx*v(31,0)
               v(34,1) = paz*v(31,1) + wpz*v(31,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(15,1) = pax*v(12,1) + wpx*v(12,0) &
                  + 1.0_dp*oo2z*(v(11,1) - rz*v(11,0)) &
                  + 1.0_dp*oo2ze*v(2,0)
               v(16,1) = pay*v(12,1) + wpy*v(12,0)
               v(17,1) = paz*v(12,1) + wpz*v(12,0)
               v(18,1) = qcx*v(8,1) + wqx*v(8,0)
               v(19,1) = pay*v(14,1) + wpy*v(14,0)
               v(20,1) = paz*v(14,1) + wpz*v(14,0) &
                  + 1.0_dp*oo2z*(v(11,1) - rz*v(11,0))
               v(25,1) = pax*v(22,1) + wpx*v(22,0) &
                  + 1.0_dp*oo2z*(v(21,1) - rz*v(21,0))
               v(26,1) = pay*v(22,1) + wpy*v(22,0) &
                  + 1.0_dp*oo2ze*v(2,0)
               v(27,1) = pax*v(24,1) + wpx*v(24,0)
               v(28,1) = qcy*v(8,1) + wqy*v(8,0) &
                  + 2.0_dp*oo2ze*v(3,0)
               v(29,1) = pay*v(24,1) + wpy*v(24,0) &
                  + 1.0_dp*oo2ze*v(4,0)
               v(30,1) = paz*v(24,1) + wpz*v(24,0) &
                  + 1.0_dp*oo2z*(v(21,1) - rz*v(21,0))
               v(35,1) = pax*v(32,1) + wpx*v(32,0) &
                  + 1.0_dp*oo2z*(v(31,1) - rz*v(31,0))
               v(36,1) = pay*v(32,1) + wpy*v(32,0)
               v(37,1) = pax*v(34,1) + wpx*v(34,0)
               v(38,1) = qcz*v(8,1) + wqz*v(8,0)
               v(39,1) = pay*v(34,1) + wpy*v(34,0)
               v(40,1) = paz*v(34,1) + wpz*v(34,0) &
                  + 1.0_dp*oo2z*(v(31,1) - rz*v(31,0)) &
                  + 1.0_dp*oo2ze*v(4,0)

            do k = 1, 40
               g(k) = g(k) + v(k,1)
            end do
         end do

               out(1) = out(1) + g(15)
               out(2) = out(2) + g(16)
               out(3) = out(3) + g(17)
               out(4) = out(4) + g(18)
               out(5) = out(5) + g(19)
               out(6) = out(6) + g(20)
               out(7) = out(7) + g(25)
               out(8) = out(8) + g(26)
               out(9) = out(9) + g(27)
               out(10) = out(10) + g(28)
               out(11) = out(11) + g(29)
               out(12) = out(12) + g(30)
               out(13) = out(13) + g(35)
               out(14) = out(14) + g(36)
               out(15) = out(15) + g(37)
               out(16) = out(16) + g(38)
               out(17) = out(17) + g(39)
               out(18) = out(18) + g(40)
      end do

   end subroutine df_2c21


   !> (a|c) class (20|2) -- 130 VRR statements after the sieve.
   pure subroutine df_2c22(nprim_a, ea, ca, ra, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_c
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a), ra(3)
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(36)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(100,0:1), g(100)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 36
         out(k) = 0.0_dp
      end do

      do ip = 1, nprim_a
         al = ea(ip)
         zeta = al
         kab = ca(ip)
         px = ra(1); py = ra(2); pz = ra(3)
         pax = 0.0_dp; pay = 0.0_dp; paz = 0.0_dp

         do k = 1, 100
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(4, tval, f)

               ! --- level m = 4 ---
               v(1,0) = pref*f(4)
               ! --- level m = 3 ---
               v(1,1) = pref*f(3)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(21,1) = qcy*v(1,1) + wqy*v(1,0)
               v(31,1) = qcz*v(1,1) + wqz*v(1,0)
               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(11,0) = qcx*v(1,0) + wqx*v(1,1)
               v(21,0) = qcy*v(1,0) + wqy*v(1,1)
               v(31,0) = qcz*v(1,0) + wqz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
