   !> (ab|c) class (00|0) -- 1 VRR statements after the sieve.
   pure subroutine df_3c000(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(1)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(1,0:1), g(1)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 1
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 1
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(0, tval, f)

               ! --- level m = 0 ---
               v(1,0) = pref*f(0)

            do k = 1, 1
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + g(1)
      end do

   end subroutine df_3c000


   !> (ab|c) class (00|1) -- 5 VRR statements after the sieve.
   pure subroutine df_3c001(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(3)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(4,0:1), g(4)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 3
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 4
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(1, tval, f)

               ! --- level m = 1 ---
               v(1,0) = pref*f(1)
               ! --- level m = 0 ---
               v(1,1) = pref*f(0)
               v(2,1) = qcx*v(1,1) + wqx*v(1,0)
               v(3,1) = qcy*v(1,1) + wqy*v(1,0)
               v(4,1) = qcz*v(1,1) + wqz*v(1,0)

            do k = 1, 4
               g(k) = g(k) + v(k,1)
            end do
         end do

               out(1) = out(1) + g(2)
               out(2) = out(2) + g(3)
               out(3) = out(3) + g(4)
      end do

   end subroutine df_3c001


   !> (ab|c) class (00|2) -- 15 VRR statements after the sieve.
   pure subroutine df_3c002(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(6)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(10,0:1), g(10)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 6
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 10
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(2, tval, f)

               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               ! --- level m = 1 ---
               v(1,1) = pref*f(1)
               v(2,1) = qcx*v(1,1) + wqx*v(1,0)
               v(3,1) = qcy*v(1,1) + wqy*v(1,0)
               v(4,1) = qcz*v(1,1) + wqz*v(1,0)
               ! --- level m = 0 ---
               v(1,0) = pref*f(0)
               v(2,0) = qcx*v(1,0) + wqx*v(1,1)
               v(3,0) = qcy*v(1,0) + wqy*v(1,1)
               v(4,0) = qcz*v(1,0) + wqz*v(1,1)
               v(5,0) = qcx*v(2,0) + wqx*v(2,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(6,0) = qcx*v(3,0) + wqx*v(3,1)
               v(7,0) = qcx*v(4,0) + wqx*v(4,1)
               v(8,0) = qcy*v(3,0) + wqy*v(3,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(9,0) = qcy*v(4,0) + wqy*v(4,1)
               v(10,0) = qcz*v(4,0) + wqz*v(4,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))

            do k = 1, 10
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + g(5)
               out(2) = out(2) + g(6)
               out(3) = out(3) + g(7)
               out(4) = out(4) + g(8)
               out(5) = out(5) + g(9)
               out(6) = out(6) + g(10)
      end do

   end subroutine df_3c002


   !> (ab|c) class (00|3) -- 31 VRR statements after the sieve.
   pure subroutine df_3c003(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
