               v(12,1) = qcy*v(5,1) + wqy*v(5,0)
               v(13,1) = qcz*v(5,1) + wqz*v(5,0)
               v(14,1) = qcx*v(8,1) + wqx*v(8,0)
               v(15,1) = qcz*v(6,1) + wqz*v(6,0)
               v(16,1) = qcx*v(10,1) + wqx*v(10,0)
               v(17,1) = qcy*v(8,1) + wqy*v(8,0) &
                  + 2.0_dp*oo2e*(v(3,1) - re*v(3,0))
               v(18,1) = qcz*v(8,1) + wqz*v(8,0)
               v(19,1) = qcy*v(10,1) + wqy*v(10,0)
               v(20,1) = qcz*v(10,1) + wqz*v(10,0) &
                  + 2.0_dp*oo2e*(v(4,1) - re*v(4,0))

            do k = 1, 20
               g(k) = g(k) + v(k,1)
            end do
         end do

               out(1) = out(1) + g(11)
               out(2) = out(2) + g(12)
               out(3) = out(3) + g(13)
