            do k = 1, 16
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + abx*g(5) &
                  + g(6)
               out(2) = out(2) + aby*g(5) &
                  + g(7)
               out(3) = out(3) + abz*g(5) &
                  + g(8)
               out(4) = out(4) + abx*g(9) &
                  + g(10)
               out(5) = out(5) + aby*g(9) &
