   !> (ab|c) class (10|0) -- 5 VRR statements after the sieve.
   pure subroutine df_3c100(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(3)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(4,0:1), g(4)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 3
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 4
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(1, tval, f)

               ! --- level m = 1 ---
               v(1,0) = pref*f(1)
               ! --- level m = 0 ---
               v(1,1) = pref*f(0)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)

            do k = 1, 4
               g(k) = g(k) + v(k,1)
            end do
         end do

               out(1) = out(1) + g(2)
               out(2) = out(2) + g(3)
               out(3) = out(3) + g(4)
      end do

   end subroutine df_3c100


   !> (ab|c) class (10|1) -- 18 VRR statements after the sieve.
   pure subroutine df_3c101(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(9)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(16,0:1), g(16)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 9
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 16
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(2, tval, f)

               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               ! --- level m = 1 ---
               v(1,1) = pref*f(1)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 0 ---
               v(1,0) = pref*f(0)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(6,0) = qcx*v(2,0) + wqx*v(2,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(7,0) = qcx*v(3,0) + wqx*v(3,1)
               v(8,0) = qcx*v(4,0) + wqx*v(4,1)
               v(10,0) = qcy*v(2,0) + wqy*v(2,1)
               v(11,0) = qcy*v(3,0) + wqy*v(3,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(12,0) = qcy*v(4,0) + wqy*v(4,1)
               v(14,0) = qcz*v(2,0) + wqz*v(2,1)
               v(15,0) = qcz*v(3,0) + wqz*v(3,1)
               v(16,0) = qcz*v(4,0) + wqz*v(4,1) &
                  + 1.0_dp*oo2ze*v(1,1)

            do k = 1, 16
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + g(6)
               out(2) = out(2) + g(7)
               out(3) = out(3) + g(8)
               out(4) = out(4) + g(10)
               out(5) = out(5) + g(11)
               out(6) = out(6) + g(12)
               out(7) = out(7) + g(14)
               out(8) = out(8) + g(15)
               out(9) = out(9) + g(16)
      end do

   end subroutine df_3c101


   !> (ab|c) class (10|2) -- 52 VRR statements after the sieve.
   pure subroutine df_3c102(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(18)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(40,0:1), g(40)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 18
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 40
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(3, tval, f)

               ! --- level m = 3 ---
               v(1,0) = pref*f(3)
               ! --- level m = 2 ---
               v(1,1) = pref*f(2)
               v(5,1) = qcx*v(1,1) + wqx*v(1,0)
               v(9,1) = qcy*v(1,1) + wqy*v(1,0)
               v(13,1) = qcz*v(1,1) + wqz*v(1,0)
               ! --- level m = 1 ---
               v(1,0) = pref*f(1)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = qcx*v(1,0) + wqx*v(1,1)
               v(9,0) = qcy*v(1,0) + wqy*v(1,1)
               v(13,0) = qcz*v(1,0) + wqz*v(1,1)
               v(6,0) = pax*v(5,0) + wpx*v(5,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(7,0) = pay*v(5,0) + wpy*v(5,1)
               v(8,0) = paz*v(5,0) + wpz*v(5,1)
               v(10,0) = pax*v(9,0) + wpx*v(9,1)
               v(11,0) = pay*v(9,0) + wpy*v(9,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(16,0) = paz*v(13,0) + wpz*v(13,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(29,0) = qcy*v(9,0) + wqy*v(9,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(37,0) = qcz*v(13,0) + wqz*v(13,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               ! --- level m = 0 ---
               v(1,1) = pref*f(0)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(9,1) = qcy*v(1,1) + wqy*v(1,0)
               v(13,1) = qcz*v(1,1) + wqz*v(1,0)
               v(6,1) = qcx*v(2,1) + wqx*v(2,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(7,1) = qcx*v(3,1) + wqx*v(3,0)
               v(8,1) = qcx*v(4,1) + wqx*v(4,0)
               v(10,1) = pax*v(9,1) + wpx*v(9,0)
               v(11,1) = pay*v(9,1) + wpy*v(9,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(16,1) = paz*v(13,1) + wpz*v(13,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(29,1) = qcy*v(9,1) + wqy*v(9,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(37,1) = qcz*v(13,1) + wqz*v(13,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(18,1) = qcx*v(6,1) + wqx*v(6,0) &
                  + 1.0_dp*oo2e*(v(2,1) - re*v(2,0)) &
                  + 1.0_dp*oo2ze*v(5,0)
               v(19,1) = qcx*v(7,1) + wqx*v(7,0) &
                  + 1.0_dp*oo2e*(v(3,1) - re*v(3,0))
               v(20,1) = qcx*v(8,1) + wqx*v(8,0) &
                  + 1.0_dp*oo2e*(v(4,1) - re*v(4,0))
               v(22,1) = qcy*v(6,1) + wqy*v(6,0)
               v(23,1) = qcx*v(11,1) + wqx*v(11,0)
               v(24,1) = qcy*v(8,1) + wqy*v(8,0)
               v(26,1) = qcz*v(6,1) + wqz*v(6,0)
               v(27,1) = qcz*v(7,1) + wqz*v(7,0)
               v(28,1) = qcx*v(16,1) + wqx*v(16,0)
               v(30,1) = pax*v(29,1) + wpx*v(29,0)
               v(31,1) = pay*v(29,1) + wpy*v(29,0) &
                  + 2.0_dp*oo2ze*v(9,0)
               v(32,1) = paz*v(29,1) + wpz*v(29,0)
               v(34,1) = qcz*v(10,1) + wqz*v(10,0)
               v(35,1) = qcz*v(11,1) + wqz*v(11,0)
               v(36,1) = qcy*v(16,1) + wqy*v(16,0)
               v(38,1) = pax*v(37,1) + wpx*v(37,0)
               v(39,1) = pay*v(37,1) + wpy*v(37,0)
               v(40,1) = paz*v(37,1) + wpz*v(37,0) &
                  + 2.0_dp*oo2ze*v(13,0)

            do k = 1, 40
               g(k) = g(k) + v(k,1)
            end do
         end do

               out(1) = out(1) + g(18)
               out(2) = out(2) + g(19)
               out(3) = out(3) + g(20)
               out(4) = out(4) + g(22)
               out(5) = out(5) + g(23)
               out(6) = out(6) + g(24)
               out(7) = out(7) + g(26)
               out(8) = out(8) + g(27)
               out(9) = out(9) + g(28)
               out(10) = out(10) + g(30)
               out(11) = out(11) + g(31)
               out(12) = out(12) + g(32)
               out(13) = out(13) + g(34)
               out(14) = out(14) + g(35)
               out(15) = out(15) + g(36)
               out(16) = out(16) + g(38)
               out(17) = out(17) + g(39)
               out(18) = out(18) + g(40)
      end do

   end subroutine df_3c102


   !> (ab|c) class (10|3) -- 103 VRR statements after the sieve.
   pure subroutine df_3c103(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(30)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(80,0:1), g(80)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 30
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 80
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(4, tval, f)

               ! --- level m = 4 ---
               v(1,0) = pref*f(4)
               ! --- level m = 3 ---
               v(1,1) = pref*f(3)
               v(5,1) = qcx*v(1,1) + wqx*v(1,0)
               v(9,1) = qcy*v(1,1) + wqy*v(1,0)
               v(13,1) = qcz*v(1,1) + wqz*v(1,0)
               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               v(5,0) = qcx*v(1,0) + wqx*v(1,1)
               v(9,0) = qcy*v(1,0) + wqy*v(1,1)
               v(13,0) = qcz*v(1,0) + wqz*v(1,1)
               v(10,0) = pax*v(9,0) + wpx*v(9,1)
               v(12,0) = paz*v(9,0) + wpz*v(9,1)
               v(17,0) = qcx*v(5,0) + wqx*v(5,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(29,0) = qcy*v(9,0) + wqy*v(9,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(33,0) = qcy*v(13,0) + wqy*v(13,1)
               v(37,0) = qcz*v(13,0) + wqz*v(13,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               ! --- level m = 1 ---
               v(1,1) = pref*f(1)
               v(5,1) = qcx*v(1,1) + wqx*v(1,0)
               v(9,1) = qcy*v(1,1) + wqy*v(1,0)
               v(13,1) = qcz*v(1,1) + wqz*v(1,0)
               v(6,1) = pax*v(5,1) + wpx*v(5,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(7,1) = pay*v(5,1) + wpy*v(5,0)
               v(8,1) = paz*v(5,1) + wpz*v(5,0)
               v(10,1) = pax*v(9,1) + wpx*v(9,0)
               v(11,1) = pay*v(9,1) + wpy*v(9,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(12,1) = paz*v(9,1) + wpz*v(9,0)
               v(14,1) = pax*v(13,1) + wpx*v(13,0)
               v(15,1) = pay*v(13,1) + wpy*v(13,0)
               v(16,1) = paz*v(13,1) + wpz*v(13,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(17,1) = qcx*v(5,1) + wqx*v(5,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(21,1) = qcx*v(9,1) + wqx*v(9,0)
               v(29,1) = qcy*v(9,1) + wqy*v(9,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(33,1) = qcy*v(13,1) + wqy*v(13,0)
               v(37,1) = qcz*v(13,1) + wqz*v(13,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(18,1) = pax*v(17,1) + wpx*v(17,0) &
                  + 2.0_dp*oo2ze*v(5,0)
               v(19,1) = pay*v(17,1) + wpy*v(17,0)
               v(20,1) = paz*v(17,1) + wpz*v(17,0)
               v(22,1) = qcx*v(10,1) + wqx*v(10,0) &
                  + 1.0_dp*oo2ze*v(9,0)
               v(24,1) = qcx*v(12,1) + wqx*v(12,0)
               v(30,1) = pax*v(29,1) + wpx*v(29,0)
               v(31,1) = pay*v(29,1) + wpy*v(29,0) &
                  + 2.0_dp*oo2ze*v(9,0)
               v(32,1) = paz*v(29,1) + wpz*v(29,0)
               v(35,1) = pay*v(33,1) + wpy*v(33,0) &
                  + 1.0_dp*oo2ze*v(13,0)
               v(38,1) = pax*v(37,1) + wpx*v(37,0)
               v(39,1) = pay*v(37,1) + wpy*v(37,0)
               v(40,1) = paz*v(37,1) + wpz*v(37,0) &
                  + 2.0_dp*oo2ze*v(13,0)
               ! --- level m = 0 ---
               v(1,0) = pref*f(0)
               v(5,0) = qcx*v(1,0) + wqx*v(1,1)
               v(9,0) = qcy*v(1,0) + wqy*v(1,1)
               v(13,0) = qcz*v(1,0) + wqz*v(1,1)
               v(6,0) = pax*v(5,0) + wpx*v(5,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(7,0) = pay*v(5,0) + wpy*v(5,1)
               v(8,0) = paz*v(5,0) + wpz*v(5,1)
               v(10,0) = pax*v(9,0) + wpx*v(9,1)
               v(11,0) = pay*v(9,0) + wpy*v(9,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(12,0) = paz*v(9,0) + wpz*v(9,1)
               v(14,0) = pax*v(13,0) + wpx*v(13,1)
               v(15,0) = pay*v(13,0) + wpy*v(13,1)
               v(16,0) = paz*v(13,0) + wpz*v(13,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(17,0) = qcx*v(5,0) + wqx*v(5,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(29,0) = qcy*v(9,0) + wqy*v(9,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(37,0) = qcz*v(13,0) + wqz*v(13,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(18,0) = pax*v(17,0) + wpx*v(17,1) &
                  + 2.0_dp*oo2ze*v(5,1)
               v(19,0) = pay*v(17,0) + wpy*v(17,1)
               v(20,0) = paz*v(17,0) + wpz*v(17,1)
               v(22,0) = qcy*v(6,0) + wqy*v(6,1)
               v(24,0) = qcx*v(12,0) + wqx*v(12,1)
               v(30,0) = pax*v(29,0) + wpx*v(29,1)
               v(31,0) = pay*v(29,0) + wpy*v(29,1) &
                  + 2.0_dp*oo2ze*v(9,1)
               v(32,0) = paz*v(29,0) + wpz*v(29,1)
               v(35,0) = qcz*v(11,0) + wqz*v(11,1)
               v(38,0) = pax*v(37,0) + wpx*v(37,1)
               v(39,0) = pay*v(37,0) + wpy*v(37,1)
               v(40,0) = paz*v(37,0) + wpz*v(37,1) &
                  + 2.0_dp*oo2ze*v(13,1)
               v(42,0) = qcx*v(18,0) + wqx*v(18,1) &
                  + 2.0_dp*oo2e*(v(6,0) - re*v(6,1)) &
                  + 1.0_dp*oo2ze*v(17,1)
               v(43,0) = qcx*v(19,0) + wqx*v(19,1) &
                  + 2.0_dp*oo2e*(v(7,0) - re*v(7,1))
               v(44,0) = qcx*v(20,0) + wqx*v(20,1) &
                  + 2.0_dp*oo2e*(v(8,0) - re*v(8,1))
               v(46,0) = qcy*v(18,0) + wqy*v(18,1)
               v(47,0) = qcy*v(19,0) + wqy*v(19,1) &
                  + 1.0_dp*oo2ze*v(17,1)
               v(48,0) = qcy*v(20,0) + wqy*v(20,1)
               v(50,0) = qcz*v(18,0) + wqz*v(18,1)
               v(51,0) = qcz*v(19,0) + wqz*v(19,1)
               v(52,0) = qcz*v(20,0) + wqz*v(20,1) &
                  + 1.0_dp*oo2ze*v(17,1)
               v(54,0) = qcx*v(30,0) + wqx*v(30,1) &
                  + 1.0_dp*oo2ze*v(29,1)
               v(55,0) = qcx*v(31,0) + wqx*v(31,1)
               v(56,0) = qcx*v(32,0) + wqx*v(32,1)
               v(58,0) = qcz*v(22,0) + wqz*v(22,1)
               v(59,0) = qcx*v(35,0) + wqx*v(35,1)
               v(60,0) = qcz*v(24,0) + wqz*v(24,1) &
                  + 1.0_dp*oo2ze*v(21,1)
               v(62,0) = qcx*v(38,0) + wqx*v(38,1) &
                  + 1.0_dp*oo2ze*v(37,1)
               v(63,0) = qcx*v(39,0) + wqx*v(39,1)
               v(64,0) = qcx*v(40,0) + wqx*v(40,1)
               v(66,0) = qcy*v(30,0) + wqy*v(30,1) &
                  + 2.0_dp*oo2e*(v(10,0) - re*v(10,1))
               v(67,0) = qcy*v(31,0) + wqy*v(31,1) &
                  + 2.0_dp*oo2e*(v(11,0) - re*v(11,1)) &
                  + 1.0_dp*oo2ze*v(29,1)
               v(68,0) = qcy*v(32,0) + wqy*v(32,1) &
                  + 2.0_dp*oo2e*(v(12,0) - re*v(12,1))
               v(70,0) = qcz*v(30,0) + wqz*v(30,1)
               v(71,0) = qcz*v(31,0) + wqz*v(31,1)
               v(72,0) = qcz*v(32,0) + wqz*v(32,1) &
                  + 1.0_dp*oo2ze*v(29,1)
               v(74,0) = qcy*v(38,0) + wqy*v(38,1)
               v(75,0) = qcy*v(39,0) + wqy*v(39,1) &
                  + 1.0_dp*oo2ze*v(37,1)
               v(76,0) = qcy*v(40,0) + wqy*v(40,1)
               v(78,0) = qcz*v(38,0) + wqz*v(38,1) &
                  + 2.0_dp*oo2e*(v(14,0) - re*v(14,1))
               v(79,0) = qcz*v(39,0) + wqz*v(39,1) &
                  + 2.0_dp*oo2e*(v(15,0) - re*v(15,1))
               v(80,0) = qcz*v(40,0) + wqz*v(40,1) &
                  + 2.0_dp*oo2e*(v(16,0) - re*v(16,1)) &
                  + 1.0_dp*oo2ze*v(37,1)

            do k = 1, 80
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + g(42)
               out(2) = out(2) + g(43)
               out(3) = out(3) + g(44)
               out(4) = out(4) + g(46)
               out(5) = out(5) + g(47)
               out(6) = out(6) + g(48)
               out(7) = out(7) + g(50)
               out(8) = out(8) + g(51)
               out(9) = out(9) + g(52)
               out(10) = out(10) + g(54)
               out(11) = out(11) + g(55)
               out(12) = out(12) + g(56)
               out(13) = out(13) + g(58)
               out(14) = out(14) + g(59)
               out(15) = out(15) + g(60)
               out(16) = out(16) + g(62)
               out(17) = out(17) + g(63)
               out(18) = out(18) + g(64)
               out(19) = out(19) + g(66)
               out(20) = out(20) + g(67)
               out(21) = out(21) + g(68)
               out(22) = out(22) + g(70)
               out(23) = out(23) + g(71)
               out(24) = out(24) + g(72)
               out(25) = out(25) + g(74)
               out(26) = out(26) + g(75)
               out(27) = out(27) + g(76)
               out(28) = out(28) + g(78)
               out(29) = out(29) + g(79)
               out(30) = out(30) + g(80)
      end do

   end subroutine df_3c103


   !> (ab|c) class (11|0) -- 15 VRR statements after the sieve.
   pure subroutine df_3c110(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(9)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(10,0:1), g(10)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 9
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 10
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(2, tval, f)

               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               ! --- level m = 1 ---
               v(1,1) = pref*f(1)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 0 ---
               v(1,0) = pref*f(0)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(6,0) = pax*v(3,0) + wpx*v(3,1)
               v(7,0) = pax*v(4,0) + wpx*v(4,1)
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(9,0) = pay*v(4,0) + wpy*v(4,1)
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))

            do k = 1, 10
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + abx*g(2) &
                  + g(5)
               out(2) = out(2) + abx*g(3) &
                  + g(6)
               out(3) = out(3) + abx*g(4) &
                  + g(7)
               out(4) = out(4) + aby*g(2) &
                  + g(6)
               out(5) = out(5) + aby*g(3) &
                  + g(8)
               out(6) = out(6) + aby*g(4) &
                  + g(9)
               out(7) = out(7) + abz*g(2) &
                  + g(7)
               out(8) = out(8) + abz*g(3) &
                  + g(9)
               out(9) = out(9) + abz*g(4) &
                  + g(10)
      end do

   end subroutine df_3c110


