   !> (ab|c) class (11|3) -- 277 VRR statements after the sieve.
   pure subroutine df_3c113(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(90)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(200,0:1), g(200)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 90
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 200
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(5, tval, f)

               ! --- level m = 5 ---
               v(1,0) = pref*f(5)
               ! --- level m = 4 ---
               v(1,1) = pref*f(4)
               v(11,1) = qcx*v(1,1) + wqx*v(1,0)
               v(21,1) = qcy*v(1,1) + wqy*v(1,0)
               v(31,1) = qcz*v(1,1) + wqz*v(1,0)
               ! --- level m = 3 ---
               v(1,0) = pref*f(3)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(11,0) = qcx*v(1,0) + wqx*v(1,1)
               v(21,0) = qcy*v(1,0) + wqy*v(1,1)
               v(31,0) = qcz*v(1,0) + wqz*v(1,1)
               v(12,0) = pax*v(11,0) + wpx*v(11,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(13,0) = pay*v(11,0) + wpy*v(11,1)
               v(14,0) = paz*v(11,0) + wpz*v(11,1)
               v(33,0) = pay*v(31,0) + wpy*v(31,1)
               v(71,0) = qcy*v(21,0) + wqy*v(21,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               v(81,0) = qcy*v(31,0) + wqy*v(31,1)
               v(91,0) = qcz*v(31,0) + wqz*v(31,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               ! --- level m = 2 ---
               v(1,1) = pref*f(2)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(11,1) = qcx*v(1,1) + wqx*v(1,0)
               v(21,1) = qcy*v(1,1) + wqy*v(1,0)
               v(31,1) = qcz*v(1,1) + wqz*v(1,0)
               v(8,1) = pay*v(3,1) + wpy*v(3,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(12,1) = pax*v(11,1) + wpx*v(11,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(13,1) = pay*v(11,1) + wpy*v(11,0)
               v(14,1) = paz*v(11,1) + wpz*v(11,0)
               v(24,1) = paz*v(21,1) + wpz*v(21,0)
               v(32,1) = pax*v(31,1) + wpx*v(31,0)
               v(33,1) = pay*v(31,1) + wpy*v(31,0)
               v(34,1) = paz*v(31,1) + wpz*v(31,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(41,1) = qcx*v(11,1) + wqx*v(11,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(71,1) = qcy*v(21,1) + wqy*v(21,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(81,1) = qcy*v(31,1) + wqy*v(31,0)
               v(91,1) = qcz*v(31,1) + wqz*v(31,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(15,1) = pax*v(12,1) + wpx*v(12,0) &
                  + 1.0_dp*oo2z*(v(11,1) - rz*v(11,0)) &
                  + 1.0_dp*oo2ze*v(2,0)
               v(18,1) = pay*v(13,1) + wpy*v(13,0) &
                  + 1.0_dp*oo2z*(v(11,1) - rz*v(11,0))
               v(20,1) = paz*v(14,1) + wpz*v(14,0) &
