   !> (ab|c) class (12|0) -- 33 VRR statements after the sieve.
   pure subroutine df_3c120(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(18)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(20,0:1), g(20)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 18
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 20
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(3, tval, f)

               ! --- level m = 3 ---
               v(1,0) = pref*f(3)
               ! --- level m = 2 ---
               v(1,1) = pref*f(2)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 1 ---
               v(1,0) = pref*f(1)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(6,0) = pax*v(3,0) + wpx*v(3,1)
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               ! --- level m = 0 ---
               v(1,1) = pref*f(0)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(5,1) = pax*v(2,1) + wpx*v(2,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(6,1) = pax*v(3,1) + wpx*v(3,0)
               v(7,1) = pax*v(4,1) + wpx*v(4,0)
               v(8,1) = pay*v(3,1) + wpy*v(3,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(9,1) = pay*v(4,1) + wpy*v(4,0)
               v(10,1) = paz*v(4,1) + wpz*v(4,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(11,1) = pax*v(5,1) + wpx*v(5,0) &
                  + 2.0_dp*oo2z*(v(2,1) - rz*v(2,0))
               v(12,1) = pay*v(5,1) + wpy*v(5,0)
               v(13,1) = paz*v(5,1) + wpz*v(5,0)
               v(14,1) = pax*v(8,1) + wpx*v(8,0)
               v(15,1) = paz*v(6,1) + wpz*v(6,0)
               v(16,1) = pax*v(10,1) + wpx*v(10,0)
               v(17,1) = pay*v(8,1) + wpy*v(8,0) &
                  + 2.0_dp*oo2z*(v(3,1) - rz*v(3,0))
               v(18,1) = paz*v(8,1) + wpz*v(8,0)
               v(19,1) = pay*v(10,1) + wpy*v(10,0)
               v(20,1) = paz*v(10,1) + wpz*v(10,0) &
                  + 2.0_dp*oo2z*(v(4,1) - rz*v(4,0))

            do k = 1, 20
               g(k) = g(k) + v(k,1)
            end do
         end do

               out(1) = out(1) + abx*abx*g(2) &
                  + 2.0_dp*abx*g(5) &
                  + g(11)
               out(2) = out(2) + abx*abx*g(3) &
                  + 2.0_dp*abx*g(6) &
                  + g(12)
               out(3) = out(3) + abx*abx*g(4) &
                  + 2.0_dp*abx*g(7) &
                  + g(13)
               out(4) = out(4) + abx*aby*g(2) &
                  + abx*g(6) &
                  + aby*g(5) &
                  + g(12)
               out(5) = out(5) + abx*aby*g(3) &
                  + abx*g(8) &
                  + aby*g(6) &
                  + g(14)
               out(6) = out(6) + abx*aby*g(4) &
                  + abx*g(9) &
                  + aby*g(7) &
                  + g(15)
               out(7) = out(7) + abx*abz*g(2) &
                  + abx*g(7) &
                  + abz*g(5) &
                  + g(13)
               out(8) = out(8) + abx*abz*g(3) &
                  + abx*g(9) &
                  + abz*g(6) &
                  + g(15)
               out(9) = out(9) + abx*abz*g(4) &
                  + abx*g(10) &
                  + abz*g(7) &
                  + g(16)
               out(10) = out(10) + aby*aby*g(2) &
                  + 2.0_dp*aby*g(6) &
                  + g(14)
               out(11) = out(11) + aby*aby*g(3) &
                  + 2.0_dp*aby*g(8) &
                  + g(17)
               out(12) = out(12) + aby*aby*g(4) &
                  + 2.0_dp*aby*g(9) &
                  + g(18)
               out(13) = out(13) + aby*abz*g(2) &
                  + aby*g(7) &
                  + abz*g(6) &
                  + g(15)
               out(14) = out(14) + aby*abz*g(3) &
                  + aby*g(9) &
                  + abz*g(8) &
                  + g(18)
               out(15) = out(15) + aby*abz*g(4) &
                  + aby*g(10) &
                  + abz*g(9) &
                  + g(19)
               out(16) = out(16) + abz*abz*g(2) &
                  + 2.0_dp*abz*g(7) &
                  + g(16)
               out(17) = out(17) + abz*abz*g(3) &
                  + 2.0_dp*abz*g(9) &
                  + g(19)
               out(18) = out(18) + abz*abz*g(4) &
                  + 2.0_dp*abz*g(10) &
                  + g(20)
      end do

   end subroutine df_3c120


   !> (ab|c) class (12|1) -- 111 VRR statements after the sieve.
   pure subroutine df_3c121(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(54)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(80,0:1), g(80)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 54
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 80
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(4, tval, f)

               ! --- level m = 4 ---
               v(1,0) = pref*f(4)
               ! --- level m = 3 ---
               v(1,1) = pref*f(3)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(7,0) = pax*v(4,0) + wpx*v(4,1)
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(44,0) = qcy*v(4,0) + wqy*v(4,1)
               ! --- level m = 1 ---
               v(1,1) = pref*f(1)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(5,1) = pax*v(2,1) + wpx*v(2,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(6,1) = pax*v(3,1) + wpx*v(3,0)
               v(7,1) = pax*v(4,1) + wpx*v(4,0)
               v(8,1) = pay*v(3,1) + wpy*v(3,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(9,1) = pay*v(4,1) + wpy*v(4,0)
               v(10,1) = paz*v(4,1) + wpz*v(4,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(22,1) = qcx*v(2,1) + wqx*v(2,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(42,1) = qcy*v(2,1) + wqy*v(2,0)
               v(43,1) = qcy*v(3,1) + wqy*v(3,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(44,1) = qcy*v(4,1) + wqy*v(4,0)
               v(62,1) = qcz*v(2,1) + wqz*v(2,0)
               v(14,1) = pax*v(8,1) + wpx*v(8,0)
               v(15,1) = pay*v(7,1) + wpy*v(7,0)
               v(17,1) = pay*v(8,1) + wpy*v(8,0) &
                  + 2.0_dp*oo2z*(v(3,1) - rz*v(3,0))
               v(18,1) = paz*v(8,1) + wpz*v(8,0)
               v(20,1) = paz*v(10,1) + wpz*v(10,0) &
                  + 2.0_dp*oo2z*(v(4,1) - rz*v(4,0))
               v(25,1) = qcx*v(5,1) + wqx*v(5,0) &
                  + 2.0_dp*oo2ze*v(2,0)
               v(30,1) = qcx*v(10,1) + wqx*v(10,0)
               v(45,1) = qcy*v(5,1) + wqy*v(5,0)
               v(47,1) = pax*v(44,1) + wpx*v(44,0)
               v(49,1) = pay*v(44,1) + wpy*v(44,0) &
                  + 1.0_dp*oo2ze*v(4,0)
               v(65,1) = qcz*v(5,1) + wqz*v(5,0)
               v(70,1) = qcz*v(10,1) + wqz*v(10,0) &
                  + 2.0_dp*oo2ze*v(4,0)
               ! --- level m = 0 ---
               v(1,0) = pref*f(0)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(9,0) = pay*v(4,0) + wpy*v(4,1)
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(22,0) = qcx*v(2,0) + wqx*v(2,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(23,0) = qcx*v(3,0) + wqx*v(3,1)
               v(24,0) = qcx*v(4,0) + wqx*v(4,1)
               v(42,0) = qcy*v(2,0) + wqy*v(2,1)
               v(43,0) = qcy*v(3,0) + wqy*v(3,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(44,0) = qcy*v(4,0) + wqy*v(4,1)
               v(62,0) = qcz*v(2,0) + wqz*v(2,1)
               v(63,0) = qcz*v(3,0) + wqz*v(3,1)
               v(64,0) = qcz*v(4,0) + wqz*v(4,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(14,0) = pax*v(8,0) + wpx*v(8,1)
               v(15,0) = pax*v(9,0) + wpx*v(9,1)
               v(17,0) = pay*v(8,0) + wpy*v(8,1) &
                  + 2.0_dp*oo2z*(v(3,0) - rz*v(3,1))
               v(18,0) = paz*v(8,0) + wpz*v(8,1)
               v(20,0) = paz*v(10,0) + wpz*v(10,1) &
                  + 2.0_dp*oo2z*(v(4,0) - rz*v(4,1))
               v(25,0) = qcx*v(5,0) + wqx*v(5,1) &
                  + 2.0_dp*oo2ze*v(2,1)
               v(26,0) = pay*v(22,0) + wpy*v(22,1)
               v(27,0) = paz*v(22,0) + wpz*v(22,1)
               v(28,0) = qcx*v(8,0) + wqx*v(8,1)
               v(29,0) = qcx*v(9,0) + wqx*v(9,1)
               v(30,0) = qcx*v(10,0) + wqx*v(10,1)
               v(45,0) = qcy*v(5,0) + wqy*v(5,1)
               v(46,0) = pax*v(43,0) + wpx*v(43,1)
               v(47,0) = pax*v(44,0) + wpx*v(44,1)
               v(48,0) = qcy*v(8,0) + wqy*v(8,1) &
                  + 2.0_dp*oo2ze*v(3,1)
               v(49,0) = paz*v(43,0) + wpz*v(43,1)
               v(50,0) = qcy*v(10,0) + wqy*v(10,1)
               v(65,0) = qcz*v(5,0) + wqz*v(5,1)
               v(66,0) = pay*v(62,0) + wpy*v(62,1)
               v(67,0) = paz*v(62,0) + wpz*v(62,1) &
                  + 1.0_dp*oo2ze*v(2,1)
               v(68,0) = qcz*v(8,0) + wqz*v(8,1)
               v(69,0) = qcz*v(9,0) + wqz*v(9,1) &
                  + 1.0_dp*oo2ze*v(3,1)
               v(70,0) = qcz*v(10,0) + wqz*v(10,1) &
                  + 2.0_dp*oo2ze*v(4,1)
               v(31,0) = pax*v(25,0) + wpx*v(25,1) &
                  + 2.0_dp*oo2z*(v(22,0) - rz*v(22,1)) &
                  + 1.0_dp*oo2ze*v(5,1)
               v(32,0) = pay*v(25,0) + wpy*v(25,1)
               v(33,0) = paz*v(25,0) + wpz*v(25,1)
               v(34,0) = qcx*v(14,0) + wqx*v(14,1) &
                  + 1.0_dp*oo2ze*v(8,1)
               v(35,0) = qcx*v(15,0) + wqx*v(15,1) &
                  + 1.0_dp*oo2ze*v(9,1)
               v(36,0) = pax*v(30,0) + wpx*v(30,1) &
                  + 1.0_dp*oo2ze*v(10,1)
               v(37,0) = qcx*v(17,0) + wqx*v(17,1)
               v(38,0) = qcx*v(18,0) + wqx*v(18,1)
               v(39,0) = pay*v(30,0) + wpy*v(30,1)
               v(40,0) = qcx*v(20,0) + wqx*v(20,1)
               v(51,0) = pax*v(45,0) + wpx*v(45,1) &
                  + 2.0_dp*oo2z*(v(42,0) - rz*v(42,1))
               v(52,0) = pay*v(45,0) + wpy*v(45,1) &
                  + 1.0_dp*oo2ze*v(5,1)
               v(53,0) = paz*v(45,0) + wpz*v(45,1)
               v(54,0) = qcy*v(14,0) + wqy*v(14,1) &
                  + 2.0_dp*oo2ze*v(6,1)
               v(55,0) = pax*v(49,0) + wpx*v(49,1)
               v(56,0) = paz*v(47,0) + wpz*v(47,1) &
                  + 1.0_dp*oo2z*(v(42,0) - rz*v(42,1))
               v(57,0) = qcy*v(17,0) + wqy*v(17,1) &
                  + 3.0_dp*oo2ze*v(8,1)
               v(58,0) = qcy*v(18,0) + wqy*v(18,1) &
                  + 2.0_dp*oo2ze*v(9,1)
               v(59,0) = paz*v(49,0) + wpz*v(49,1) &
                  + 1.0_dp*oo2z*(v(43,0) - rz*v(43,1))
               v(60,0) = qcy*v(20,0) + wqy*v(20,1)
               v(71,0) = pax*v(65,0) + wpx*v(65,1) &
                  + 2.0_dp*oo2z*(v(62,0) - rz*v(62,1))
               v(72,0) = pay*v(65,0) + wpy*v(65,1)
               v(73,0) = paz*v(65,0) + wpz*v(65,1) &
                  + 1.0_dp*oo2ze*v(5,1)
               v(74,0) = qcz*v(14,0) + wqz*v(14,1)
               v(75,0) = qcz*v(15,0) + wqz*v(15,1) &
                  + 1.0_dp*oo2ze*v(6,1)
               v(76,0) = pax*v(70,0) + wpx*v(70,1)
               v(77,0) = qcz*v(17,0) + wqz*v(17,1)
               v(78,0) = qcz*v(18,0) + wqz*v(18,1) &
                  + 1.0_dp*oo2ze*v(8,1)
               v(79,0) = pay*v(70,0) + wpy*v(70,1)
               v(80,0) = qcz*v(20,0) + wqz*v(20,1) &
                  + 3.0_dp*oo2ze*v(10,1)

            do k = 1, 80
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + abx*abx*g(22) &
                  + 2.0_dp*abx*g(25) &
                  + g(31)
               out(2) = out(2) + abx*abx*g(23) &
                  + 2.0_dp*abx*g(26) &
                  + g(32)
               out(3) = out(3) + abx*abx*g(24) &
                  + 2.0_dp*abx*g(27) &
                  + g(33)
               out(4) = out(4) + abx*aby*g(22) &
                  + abx*g(26) &
                  + aby*g(25) &
                  + g(32)
               out(5) = out(5) + abx*aby*g(23) &
                  + abx*g(28) &
                  + aby*g(26) &
                  + g(34)
               out(6) = out(6) + abx*aby*g(24) &
                  + abx*g(29) &
                  + aby*g(27) &
                  + g(35)
               out(7) = out(7) + abx*abz*g(22) &
                  + abx*g(27) &
                  + abz*g(25) &
                  + g(33)
               out(8) = out(8) + abx*abz*g(23) &
                  + abx*g(29) &
                  + abz*g(26) &
                  + g(35)
               out(9) = out(9) + abx*abz*g(24) &
                  + abx*g(30) &
                  + abz*g(27) &
                  + g(36)
               out(10) = out(10) + aby*aby*g(22) &
                  + 2.0_dp*aby*g(26) &
                  + g(34)
               out(11) = out(11) + aby*aby*g(23) &
                  + 2.0_dp*aby*g(28) &
                  + g(37)
               out(12) = out(12) + aby*aby*g(24) &
                  + 2.0_dp*aby*g(29) &
                  + g(38)
               out(13) = out(13) + aby*abz*g(22) &
                  + aby*g(27) &
                  + abz*g(26) &
                  + g(35)
               out(14) = out(14) + aby*abz*g(23) &
                  + aby*g(29) &
                  + abz*g(28) &
                  + g(38)
               out(15) = out(15) + aby*abz*g(24) &
                  + aby*g(30) &
                  + abz*g(29) &
                  + g(39)
               out(16) = out(16) + abz*abz*g(22) &
                  + 2.0_dp*abz*g(27) &
                  + g(36)
               out(17) = out(17) + abz*abz*g(23) &
                  + 2.0_dp*abz*g(29) &
                  + g(39)
               out(18) = out(18) + abz*abz*g(24) &
                  + 2.0_dp*abz*g(30) &
                  + g(40)
               out(19) = out(19) + abx*abx*g(42) &
                  + 2.0_dp*abx*g(45) &
                  + g(51)
               out(20) = out(20) + abx*abx*g(43) &
                  + 2.0_dp*abx*g(46) &
                  + g(52)
               out(21) = out(21) + abx*abx*g(44) &
                  + 2.0_dp*abx*g(47) &
                  + g(53)
               out(22) = out(22) + abx*aby*g(42) &
                  + abx*g(46) &
                  + aby*g(45) &
                  + g(52)
               out(23) = out(23) + abx*aby*g(43) &
                  + abx*g(48) &
                  + aby*g(46) &
                  + g(54)
               out(24) = out(24) + abx*aby*g(44) &
                  + abx*g(49) &
                  + aby*g(47) &
                  + g(55)
               out(25) = out(25) + abx*abz*g(42) &
                  + abx*g(47) &
                  + abz*g(45) &
                  + g(53)
               out(26) = out(26) + abx*abz*g(43) &
                  + abx*g(49) &
                  + abz*g(46) &
                  + g(55)
               out(27) = out(27) + abx*abz*g(44) &
                  + abx*g(50) &
                  + abz*g(47) &
                  + g(56)
               out(28) = out(28) + aby*aby*g(42) &
                  + 2.0_dp*aby*g(46) &
                  + g(54)
               out(29) = out(29) + aby*aby*g(43) &
                  + 2.0_dp*aby*g(48) &
                  + g(57)
               out(30) = out(30) + aby*aby*g(44) &
                  + 2.0_dp*aby*g(49) &
                  + g(58)
               out(31) = out(31) + aby*abz*g(42) &
                  + aby*g(47) &
                  + abz*g(46) &
                  + g(55)
               out(32) = out(32) + aby*abz*g(43) &
                  + aby*g(49) &
                  + abz*g(48) &
                  + g(58)
               out(33) = out(33) + aby*abz*g(44) &
                  + aby*g(50) &
                  + abz*g(49) &
                  + g(59)
               out(34) = out(34) + abz*abz*g(42) &
                  + 2.0_dp*abz*g(47) &
                  + g(56)
               out(35) = out(35) + abz*abz*g(43) &
                  + 2.0_dp*abz*g(49) &
                  + g(59)
               out(36) = out(36) + abz*abz*g(44) &
                  + 2.0_dp*abz*g(50) &
                  + g(60)
               out(37) = out(37) + abx*abx*g(62) &
                  + 2.0_dp*abx*g(65) &
                  + g(71)
               out(38) = out(38) + abx*abx*g(63) &
                  + 2.0_dp*abx*g(66) &
                  + g(72)
               out(39) = out(39) + abx*abx*g(64) &
                  + 2.0_dp*abx*g(67) &
                  + g(73)
               out(40) = out(40) + abx*aby*g(62) &
                  + abx*g(66) &
                  + aby*g(65) &
                  + g(72)
               out(41) = out(41) + abx*aby*g(63) &
                  + abx*g(68) &
                  + aby*g(66) &
                  + g(74)
               out(42) = out(42) + abx*aby*g(64) &
                  + abx*g(69) &
                  + aby*g(67) &
                  + g(75)
               out(43) = out(43) + abx*abz*g(62) &
                  + abx*g(67) &
                  + abz*g(65) &
                  + g(73)
               out(44) = out(44) + abx*abz*g(63) &
                  + abx*g(69) &
                  + abz*g(66) &
                  + g(75)
               out(45) = out(45) + abx*abz*g(64) &
                  + abx*g(70) &
                  + abz*g(67) &
                  + g(76)
               out(46) = out(46) + aby*aby*g(62) &
                  + 2.0_dp*aby*g(66) &
                  + g(74)
               out(47) = out(47) + aby*aby*g(63) &
                  + 2.0_dp*aby*g(68) &
                  + g(77)
               out(48) = out(48) + aby*aby*g(64) &
                  + 2.0_dp*aby*g(69) &
                  + g(78)
               out(49) = out(49) + aby*abz*g(62) &
                  + aby*g(67) &
                  + abz*g(66) &
                  + g(75)
               out(50) = out(50) + aby*abz*g(63) &
                  + aby*g(69) &
                  + abz*g(68) &
                  + g(78)
               out(51) = out(51) + aby*abz*g(64) &
                  + aby*g(70) &
                  + abz*g(69) &
                  + g(79)
               out(52) = out(52) + abz*abz*g(62) &
                  + 2.0_dp*abz*g(67) &
                  + g(76)
               out(53) = out(53) + abz*abz*g(63) &
                  + 2.0_dp*abz*g(69) &
                  + g(79)
               out(54) = out(54) + abz*abz*g(64) &
                  + 2.0_dp*abz*g(70) &
                  + g(80)
      end do

   end subroutine df_3c121


   !> (ab|c) class (12|2) -- 299 VRR statements after the sieve.
   pure subroutine df_3c122(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(108)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(200,0:1), g(200)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 108
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 200
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(5, tval, f)

