               v(161,1) = qcy*v(61,1) + wqy*v(61,0)
               v(181,1) = qcz*v(61,1) + wqz*v(61,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(17,1) = pay*v(8,1) + wpy*v(8,0) &
