               v(82,1) = pax*v(81,1) + wpx*v(81,0) &
                  + 2.0_dp*oo2ze*v(21,0)
               v(83,1) = pay*v(81,1) + wpy*v(81,0)
               v(104,1) = qcx*v(44,1) + wqx*v(44,0)
               v(143,1) = pay*v(141,1) + wpy*v(141,0) &
                  + 2.0_dp*oo2ze*v(41,0)
               v(163,1) = pay*v(161,1) + wpy*v(161,0) &
                  + 1.0_dp*oo2ze*v(61,0)
               v(182,1) = pax*v(181,1) + wpx*v(181,0)
