               v(15,1) = pax*v(12,1) + wpx*v(12,0) &
                  + 1.0_dp*oo2z*(v(11,1) - rz*v(11,0)) &
                  + 1.0_dp*oo2ze*v(2,0)
               v(16,1) = pay*v(12,1) + wpy*v(12,0)
               v(17,1) = paz*v(12,1) + wpz*v(12,0)
               v(18,1) = qcx*v(8,1) + wqx*v(8,0)
