   !> (ab|c) class (22|0) -- 61 VRR statements after the sieve.
   pure subroutine df_3c220(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(36)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(35,0:1), g(35)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 36
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 35
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(4, tval, f)

               ! --- level m = 4 ---
               v(1,0) = pref*f(4)
               ! --- level m = 3 ---
               v(1,1) = pref*f(3)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 2 ---
               v(1,0) = pref*f(2)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               ! --- level m = 1 ---
               v(1,1) = pref*f(1)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(5,1) = pax*v(2,1) + wpx*v(2,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(6,1) = pax*v(3,1) + wpx*v(3,0)
               v(8,1) = pay*v(3,1) + wpy*v(3,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(10,1) = paz*v(4,1) + wpz*v(4,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(11,1) = pax*v(5,1) + wpx*v(5,0) &
                  + 2.0_dp*oo2z*(v(2,1) - rz*v(2,0))
               v(13,1) = paz*v(5,1) + wpz*v(5,0)
               v(14,1) = pax*v(8,1) + wpx*v(8,0)
               v(17,1) = pay*v(8,1) + wpy*v(8,0) &
                  + 2.0_dp*oo2z*(v(3,1) - rz*v(3,0))
               v(19,1) = pay*v(10,1) + wpy*v(10,0)
               v(20,1) = paz*v(10,1) + wpz*v(10,0) &
                  + 2.0_dp*oo2z*(v(4,1) - rz*v(4,0))
               ! --- level m = 0 ---
               v(1,0) = pref*f(0)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(6,0) = pax*v(3,0) + wpx*v(3,1)
               v(7,0) = pax*v(4,0) + wpx*v(4,1)
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(9,0) = pay*v(4,0) + wpy*v(4,1)
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(11,0) = pax*v(5,0) + wpx*v(5,1) &
                  + 2.0_dp*oo2z*(v(2,0) - rz*v(2,1))
               v(12,0) = pay*v(5,0) + wpy*v(5,1)
               v(13,0) = paz*v(5,0) + wpz*v(5,1)
               v(14,0) = pax*v(8,0) + wpx*v(8,1)
               v(15,0) = paz*v(6,0) + wpz*v(6,1)
               v(16,0) = pax*v(10,0) + wpx*v(10,1)
               v(17,0) = pay*v(8,0) + wpy*v(8,1) &
                  + 2.0_dp*oo2z*(v(3,0) - rz*v(3,1))
               v(18,0) = paz*v(8,0) + wpz*v(8,1)
               v(19,0) = pay*v(10,0) + wpy*v(10,1)
               v(20,0) = paz*v(10,0) + wpz*v(10,1) &
                  + 2.0_dp*oo2z*(v(4,0) - rz*v(4,1))
               v(21,0) = pax*v(11,0) + wpx*v(11,1) &
                  + 3.0_dp*oo2z*(v(5,0) - rz*v(5,1))
               v(22,0) = pay*v(11,0) + wpy*v(11,1)
               v(23,0) = paz*v(11,0) + wpz*v(11,1)
               v(24,0) = pax*v(14,0) + wpx*v(14,1) &
                  + 1.0_dp*oo2z*(v(8,0) - rz*v(8,1))
               v(25,0) = pay*v(13,0) + wpy*v(13,1)
               v(26,0) = paz*v(13,0) + wpz*v(13,1) &
                  + 1.0_dp*oo2z*(v(5,0) - rz*v(5,1))
               v(27,0) = pax*v(17,0) + wpx*v(17,1)
               v(28,0) = paz*v(14,0) + wpz*v(14,1)
               v(29,0) = pax*v(19,0) + wpx*v(19,1)
               v(30,0) = pax*v(20,0) + wpx*v(20,1)
               v(31,0) = pay*v(17,0) + wpy*v(17,1) &
                  + 3.0_dp*oo2z*(v(8,0) - rz*v(8,1))
               v(32,0) = paz*v(17,0) + wpz*v(17,1)
               v(33,0) = pay*v(19,0) + wpy*v(19,1) &
                  + 1.0_dp*oo2z*(v(10,0) - rz*v(10,1))
               v(34,0) = pay*v(20,0) + wpy*v(20,1)
               v(35,0) = paz*v(20,0) + wpz*v(20,1) &
                  + 3.0_dp*oo2z*(v(10,0) - rz*v(10,1))

            do k = 1, 35
               g(k) = g(k) + v(k,0)
            end do
         end do

               out(1) = out(1) + abx*abx*g(5) &
                  + 2.0_dp*abx*g(11) &
                  + g(21)
               out(2) = out(2) + abx*abx*g(6) &
                  + 2.0_dp*abx*g(12) &
                  + g(22)
               out(3) = out(3) + abx*abx*g(7) &
                  + 2.0_dp*abx*g(13) &
                  + g(23)
               out(4) = out(4) + abx*abx*g(8) &
                  + 2.0_dp*abx*g(14) &
                  + g(24)
               out(5) = out(5) + abx*abx*g(9) &
                  + 2.0_dp*abx*g(15) &
                  + g(25)
               out(6) = out(6) + abx*abx*g(10) &
                  + 2.0_dp*abx*g(16) &
                  + g(26)
               out(7) = out(7) + abx*aby*g(5) &
                  + abx*g(12) &
                  + aby*g(11) &
                  + g(22)
               out(8) = out(8) + abx*aby*g(6) &
                  + abx*g(14) &
                  + aby*g(12) &
                  + g(24)
               out(9) = out(9) + abx*aby*g(7) &
                  + abx*g(15) &
                  + aby*g(13) &
                  + g(25)
               out(10) = out(10) + abx*aby*g(8) &
                  + abx*g(17) &
                  + aby*g(14) &
                  + g(27)
               out(11) = out(11) + abx*aby*g(9) &
                  + abx*g(18) &
                  + aby*g(15) &
                  + g(28)
               out(12) = out(12) + abx*aby*g(10) &
                  + abx*g(19) &
                  + aby*g(16) &
                  + g(29)
               out(13) = out(13) + abx*abz*g(5) &
                  + abx*g(13) &
                  + abz*g(11) &
                  + g(23)
               out(14) = out(14) + abx*abz*g(6) &
                  + abx*g(15) &
                  + abz*g(12) &
                  + g(25)
               out(15) = out(15) + abx*abz*g(7) &
                  + abx*g(16) &
                  + abz*g(13) &
                  + g(26)
               out(16) = out(16) + abx*abz*g(8) &
                  + abx*g(18) &
                  + abz*g(14) &
                  + g(28)
               out(17) = out(17) + abx*abz*g(9) &
                  + abx*g(19) &
                  + abz*g(15) &
                  + g(29)
               out(18) = out(18) + abx*abz*g(10) &
                  + abx*g(20) &
                  + abz*g(16) &
                  + g(30)
               out(19) = out(19) + aby*aby*g(5) &
                  + 2.0_dp*aby*g(12) &
                  + g(24)
               out(20) = out(20) + aby*aby*g(6) &
                  + 2.0_dp*aby*g(14) &
                  + g(27)
               out(21) = out(21) + aby*aby*g(7) &
                  + 2.0_dp*aby*g(15) &
                  + g(28)
               out(22) = out(22) + aby*aby*g(8) &
                  + 2.0_dp*aby*g(17) &
                  + g(31)
               out(23) = out(23) + aby*aby*g(9) &
                  + 2.0_dp*aby*g(18) &
                  + g(32)
               out(24) = out(24) + aby*aby*g(10) &
                  + 2.0_dp*aby*g(19) &
                  + g(33)
               out(25) = out(25) + aby*abz*g(5) &
                  + aby*g(13) &
                  + abz*g(12) &
                  + g(25)
               out(26) = out(26) + aby*abz*g(6) &
                  + aby*g(15) &
                  + abz*g(14) &
                  + g(28)
               out(27) = out(27) + aby*abz*g(7) &
                  + aby*g(16) &
                  + abz*g(15) &
                  + g(29)
               out(28) = out(28) + aby*abz*g(8) &
                  + aby*g(18) &
                  + abz*g(17) &
                  + g(32)
               out(29) = out(29) + aby*abz*g(9) &
                  + aby*g(19) &
                  + abz*g(18) &
                  + g(33)
               out(30) = out(30) + aby*abz*g(10) &
                  + aby*g(20) &
                  + abz*g(19) &
                  + g(34)
               out(31) = out(31) + abz*abz*g(5) &
                  + 2.0_dp*abz*g(13) &
                  + g(26)
               out(32) = out(32) + abz*abz*g(6) &
                  + 2.0_dp*abz*g(15) &
                  + g(29)
               out(33) = out(33) + abz*abz*g(7) &
                  + 2.0_dp*abz*g(16) &
                  + g(30)
               out(34) = out(34) + abz*abz*g(8) &
                  + 2.0_dp*abz*g(18) &
                  + g(33)
               out(35) = out(35) + abz*abz*g(9) &
                  + 2.0_dp*abz*g(19) &
                  + g(34)
               out(36) = out(36) + abz*abz*g(10) &
                  + 2.0_dp*abz*g(20) &
                  + g(35)
      end do

   end subroutine df_3c220


   !> (ab|c) class (22|1) -- 205 VRR statements after the sieve.
   pure subroutine df_3c221(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(108)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(140,0:1), g(140)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 108
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 140
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(5, tval, f)

               ! --- level m = 5 ---
               v(1,0) = pref*f(5)
               ! --- level m = 4 ---
               v(1,1) = pref*f(4)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               ! --- level m = 3 ---
               v(1,0) = pref*f(3)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(74,0) = qcy*v(4,0) + wqy*v(4,1)
               v(107,0) = qcz*v(2,0) + wqz*v(2,1)
               ! --- level m = 2 ---
               v(1,1) = pref*f(2)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(5,1) = pax*v(2,1) + wpx*v(2,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(6,1) = pax*v(3,1) + wpx*v(3,0)
               v(7,1) = pax*v(4,1) + wpx*v(4,0)
               v(8,1) = pay*v(3,1) + wpy*v(3,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(9,1) = pay*v(4,1) + wpy*v(4,0)
               v(10,1) = paz*v(4,1) + wpz*v(4,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
