   !> (ab|c) class (22|2) -- 532 VRR statements after the sieve.
   pure subroutine df_3c222(npp, ppz, ppk, ppp, ppa, abx, aby, abz, nprim_c, ec, cc_, rc, out)
      !$acc routine seq
      integer,  intent(in)  :: npp, nprim_c
      real(dp), intent(in)  :: ppz(npp), ppk(npp), ppp(3, npp), ppa(3, npp)
      real(dp), intent(in)  :: abx, aby, abz
      real(dp), intent(in)  :: ec(nprim_c), cc_(nprim_c), rc(3)
      real(dp), intent(out) :: out(216)

      integer  :: ip, kp, k, cur
      real(dp) :: al, gam, zeta, eta, zpe, rho, kab, pref
      real(dp) :: px, py, pz, pqx, pqy, pqz, tval, wc
      real(dp) :: pax, pay, paz, qcx, qcy, qcz
      real(dp) :: wpx, wpy, wpz, wqx, wqy, wqz
      real(dp) :: oo2z, oo2e, oo2ze, rz, re
      real(dp) :: v(350,0:1), g(350)
      real(dp) :: f(0:BOYS_MMAX)


      do k = 1, 216
         out(k) = 0.0_dp
      end do

      do ip = 1, npp
         zeta = ppz(ip)
         kab  = ppk(ip)
         px = ppp(1, ip); py = ppp(2, ip); pz = ppp(3, ip)
         pax = ppa(1, ip); pay = ppa(2, ip); paz = ppa(3, ip)

         do k = 1, 350
            g(k) = 0.0_dp
         end do

         do kp = 1, nprim_c
            gam = ec(kp)
            eta = gam
            zpe = zeta + eta
            rho = zeta*eta/zpe
            ! The ket is a single shell, so Q = C and QC = 0. Kept as
            ! variables rather than folded away because the VRR is emitted
            ! by the four-centre generator and expects them.
            qcx = 0.0_dp; qcy = 0.0_dp; qcz = 0.0_dp
            pqx = px - rc(1); pqy = py - rc(2); pqz = pz - rc(3)
            wc = (zeta*px + eta*rc(1))/zpe; wpx = wc - px; wqx = wc - rc(1)
            wc = (zeta*py + eta*rc(2))/zpe; wpy = wc - py; wqy = wc - rc(2)
            wc = (zeta*pz + eta*rc(3))/zpe; wpz = wc - pz; wqz = wc - rc(3)
            oo2z = 0.5_dp/zeta; oo2e = 0.5_dp/eta; oo2ze = 0.5_dp/zpe
            rz = rho/zeta; re = rho/eta
            tval = rho*(pqx*pqx + pqy*pqy + pqz*pqz)
            ! K_cd = 1: a single Gaussian has no product exponential.
            pref = TWO_PI_2_5/(zeta*eta*sqrt(zpe))*kab*cc_(kp)
            call boys_eval(6, tval, f)

               ! --- level m = 6 ---
               v(1,0) = pref*f(6)
               ! --- level m = 5 ---
               v(1,1) = pref*f(5)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(71,1) = qcy*v(1,1) + wqy*v(1,0)
               ! --- level m = 4 ---
               v(1,0) = pref*f(4)
               v(2,0) = pax*v(1,0) + wpx*v(1,1)
               v(3,0) = pay*v(1,0) + wpy*v(1,1)
               v(4,0) = paz*v(1,0) + wpz*v(1,1)
               v(36,0) = qcx*v(1,0) + wqx*v(1,1)
               v(71,0) = qcy*v(1,0) + wqy*v(1,1)
               v(5,0) = pax*v(2,0) + wpx*v(2,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(8,0) = pay*v(3,0) + wpy*v(3,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(10,0) = paz*v(4,0) + wpz*v(4,1) &
                  + 1.0_dp*oo2z*(v(1,0) - rz*v(1,1))
               v(37,0) = qcx*v(2,0) + wqx*v(2,1) &
                  + 1.0_dp*oo2ze*v(1,1)
               v(72,0) = pax*v(71,0) + wpx*v(71,1)
               v(107,0) = qcz*v(2,0) + wqz*v(2,1)
               v(108,0) = qcz*v(3,0) + wqz*v(3,1)
               v(246,0) = qcy*v(71,0) + wqy*v(71,1) &
                  + 1.0_dp*oo2e*(v(1,0) - re*v(1,1))
               ! --- level m = 3 ---
               v(1,1) = pref*f(3)
               v(2,1) = pax*v(1,1) + wpx*v(1,0)
               v(3,1) = pay*v(1,1) + wpy*v(1,0)
               v(4,1) = paz*v(1,1) + wpz*v(1,0)
               v(36,1) = qcx*v(1,1) + wqx*v(1,0)
               v(71,1) = qcy*v(1,1) + wqy*v(1,0)
               v(106,1) = qcz*v(1,1) + wqz*v(1,0)
               v(5,1) = pax*v(2,1) + wpx*v(2,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(8,1) = pay*v(3,1) + wpy*v(3,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(9,1) = pay*v(4,1) + wpy*v(4,0)
               v(10,1) = paz*v(4,1) + wpz*v(4,0) &
                  + 1.0_dp*oo2z*(v(1,1) - rz*v(1,0))
               v(37,1) = pax*v(36,1) + wpx*v(36,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(72,1) = pax*v(71,1) + wpx*v(71,0)
               v(73,1) = pay*v(71,1) + wpy*v(71,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(74,1) = paz*v(71,1) + wpz*v(71,0)
               v(107,1) = qcz*v(2,1) + wqz*v(2,0)
               v(108,1) = qcz*v(3,1) + wqz*v(3,0)
               v(109,1) = qcz*v(4,1) + wqz*v(4,0) &
                  + 1.0_dp*oo2ze*v(1,0)
               v(141,1) = qcx*v(36,1) + wqx*v(36,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(246,1) = qcy*v(71,1) + wqy*v(71,0) &
                  + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
               v(11,1) = pax*v(5,1) + wpx*v(5,0) &
                  + 2.0_dp*oo2z*(v(2,1) - rz*v(2,0))
               v(14,1) = pax*v(8,1) + wpx*v(8,0)
               v(17,1) = pay*v(8,1) + wpy*v(8,0) &
                  + 2.0_dp*oo2z*(v(3,1) - rz*v(3,0))
               v(20,1) = paz*v(10,1) + wpz*v(10,0) &
                  + 2.0_dp*oo2z*(v(4,1) - rz*v(4,0))
               v(40,1) = qcx*v(5,1) + wqx*v(5,0) &
                  + 2.0_dp*oo2ze*v(2,0)
               v(43,1) = qcx*v(8,1) + wqx*v(8,0)
               v(45,1) = qcx*v(10,1) + wqx*v(10,0)
               v(76,1) = pay*v(72,1) + wpy*v(72,0) &
                  + 1.0_dp*oo2ze*v(2,0)
               v(77,1) = paz*v(72,1) + wpz*v(72,0)
               v(80,1) = qcy*v(10,1) + wqy*v(10,0)
               v(110,1) = qcz*v(5,1) + wqz*v(5,0)
               v(114,1) = paz*v(108,1) + wpz*v(108,0) &
                  + 1.0_dp*oo2ze*v(3,0)
               v(142,1) = qcx*v(37,1) + wqx*v(37,0) &
                  + 1.0_dp*oo2e*(v(2,1) - re*v(2,0)) &
